export function pearsonCorrelation(a,b){if(!Array.isArray(a)||!Array.isArray(b)||a.length!==b.length||a.length<3) return {r:null,n:Math.min(a?.length??0,b?.length??0),meaning:'INSUFFICIENT'};const pairs=a.map((x,i)=>[x,b[i]]).filter(([x,y])=>Number.isFinite(x)&&Number.isFinite(y));if(pairs.length<3)return{r:null,n:pairs.length,meaning:'INSUFFICIENT'};const mx=pairs.reduce((s,p)=>s+p[0],0)/pairs.length,my=pairs.reduce((s,p)=>s+p[1],0)/pairs.length;let num=0,dx=0,dy=0;for(const [x,y] of pairs){num+=(x-mx)*(y-my);dx+=(x-mx)**2;dy+=(y-my)**2;}const r=dx&&dy?num/Math.sqrt(dx*dy):null;return{r,n:pairs.length,meaning:'CORRELATION_NOT_CAUSATION'};}
